import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  emptyActionClassName,
  emptyClassName,
  emptyDescriptionClassName,
  emptyIconClassName,
  emptyTitleClassName,
} from "./view";

export {
  emptyActionClassName,
  emptyClassName,
  emptyDescriptionClassName,
  emptyIconClassName,
  emptyTitleClassName,
} from "./view";

export type ViewConfig = Readonly<{
  title: string;
  description: string;
  icon?: string;
  action?: Html;
  className?: string;
}>;

const classNames = (base: string, className?: string): string =>
  [base, className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

export const view = <ParentMessage>({
  title,
  description,
  icon = "–",
  action,
  className,
}: ViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [h.Class(classNames(emptyClassName, className))],
    [
      h.div([h.Class(emptyIconClassName), h.AriaHidden(true)], [icon]),
      h.h3([h.Class(emptyTitleClassName)], [title]),
      h.p([h.Class(emptyDescriptionClassName)], [description]),
      action === undefined
        ? h.empty
        : h.div([h.Class(emptyActionClassName)], [action]),
    ]
  );
};

export const emptyClassName =
  "flex flex-col items-center justify-center rounded-lg border border-dashed border-gray-300 bg-white p-8 text-center";

export const emptyIconClassName =
  "mb-4 flex h-12 w-12 items-center justify-center rounded-full bg-gray-100 text-xl font-semibold text-gray-500";

export const emptyTitleClassName = "text-base font-semibold text-gray-950";

export const emptyDescriptionClassName =
  "mt-2 max-w-sm text-sm leading-6 text-gray-600";

export const emptyActionClassName = "mt-5";

import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { describe, test } from "vitest";

import * as Empty from "./index";

const view = (): Html =>
  Empty.view({
    title: "No projects yet",
    description: "Create a project to start collecting registry slices.",
    icon: "+",
  });

describe("Empty registry view", () => {
  test("renders the documented static surface", () => {
    Scene.scene(
      {
        update: (model: undefined): readonly [undefined, []] => [model, []],
        view,
      },
      Scene.with(undefined),
      Scene.expect(Scene.text("No projects yet")).toExist(),
      Scene.expect(
        Scene.text("Create a project to start collecting registry slices.")
      ).toExist()
    );
  });
});
